// Package api is the contract (spec/openapi.yaml) as Go types: every schema
// of the engine's HTTP API, models only, generated by oapi-codegen with the
// same settings as the engine's own package, so an enum value has the same
// name on both sides (api.SignerAnswerKindShare, api.VenueBinance). The
// contract's Decimal is a string here too; nothing is parsed into a float.
//
// Regenerate with `make gen` after the contract changes.
package api

//go:generate go run github.com/oapi-codegen/oapi-codegen/v2/cmd/oapi-codegen@v2.8.0 -config oapi-codegen.yaml ../spec/openapi.yaml
